[
  {
    "sys_consequence_reasoning": "Four more deaths is plainly the worse outcome",
    "ce_understood_harm": "the person I love gets hit and killed",
    "pda_responsibility": "I'd be the one who sent the train there"
  },
  {
    "sys_consequence_reasoning": "on paper that's more loss",
    "ce_understood_harm": "I personally end the life of someone I love",
    "pda_responsibility": "a death caused on purpose by the person closest to them",
    "pd_personal_consequence_anxiety": "everyone who knew them would know I did it"
  },
  {
    "sys_consequence_reasoning": "one loss beats five, which pushes me toward the lever",
    "ce_understood_harm": "the person I love is struck and killed on that track",
    "pd_decision_conflict": "Honestly, I can't give a clean answer"
  },
  {
    "sys_consequence_reasoning": "Fewer people dying is the reason",
    "ce_understood_harm": "The person I love would take the full hit of that train"
  },
  {
    "sys_consequence_reasoning": "Five people dying is a larger loss, I admit that",
    "ce_understood_harm": "It would crush them",
    "pda_responsibility": "their death would trace straight back to my choice"
  },
  {
    "sys_consequence_reasoning": "Saving the larger number is the better result",
    "ce_understood_harm": "the person I love dies instead of the five",
    "pda_responsibility": "I'd be responsible for it"
  },
  {
    "sys_consequence_reasoning": "if that holds, pulling saves more",
    "ce_understood_harm": "the person I love gets hit and killed",
    "pda_responsibility": "I'm the one who aimed the train at them"
  },
  {
    "sys_consequence_reasoning": "Keeping the total number of deaths as low as possible",
    "ce_understood_harm": "Someone I love would be killed by that train"
  },
  {
    "sys_consequence_reasoning": "Five people alive against one is the better result",
    "ce_understood_harm": "the person on the side track, someone I love, dies",
    "pda_responsibility": "dies because I threw that switch"
  },
  {
    "sys_consequence_reasoning": "Leaving it kills five, and that's more death",
    "ce_understood_harm": "Pulling kills someone I love, directly",
    "pda_responsibility": "by my action",
    "pd_personal_consequence_anxiety": "I'd carry being their killer for the rest of my life"
  }
]
